   239→// handleSessionStartCommon is the shared implementation for session start hooks.
   240→// Used by both Claude Code and Gemini CLI handlers.
   241→func handleSessionStartCommon() error {
   242→	ag, err := GetCurrentHookAgent()
   243→	if err != nil {
   244→		return fmt.Errorf("failed to get agent: %w", err)
   245→	}
   246→
   247→	input, err := ag.ParseHookInput(agent.HookSessionStart, os.Stdin)
   248→	if err != nil {
   249→		return fmt.Errorf("failed to parse hook input: %w", err)
   250→	}
   251→
   252→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   253→	logging.Info(logCtx, "session-start",
   254→		slog.String("hook", "session-start"),
   255→		slog.String("hook_type", "agent"),
   256→		slog.String("model_session_id", input.SessionID),
   257→		slog.String("transcript_path", input.SessionRef),
   258→	)
   259→
   260→	if input.SessionID == "" {
   261→		return errors.New("no session_id in input")
   262→	}
   263→
   264→	if IsMultiSessionWarningDisabled() {
   265→		return nil
   266→	}
   267→	// UNLESS the situation has changed (e.g., user committed, so no more conflict).
   268→	if err := checkConcurrentSessions(ag, input.SessionID); err != nil {
   269→		return err
   270→	}
   271→
   272→	return nil
   273→}
