   275→// checkConcurrentSessions checks for concurrent session conflicts and shows warnings if needed.
   276→// Returns true if the hook should be skipped due to an unresolved conflict.
   277→func checkConcurrentSessions(ag agent.Agent, sessionID string) error {
   278→	strat := GetStrategy()
   279→
   280→	concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker)
   281→	if !ok {
   282→		return nil // Strategy doesn't support concurrent checks
   283→	}
   284→
   285→	// Check for other active sessions with checkpoints (on current HEAD)
   286→	existingSessionState, checkErr := concurrentChecker.HasOtherActiveSessionsWithCheckpoints(sessionID)
   287→	hasConflict := checkErr == nil && existingSessionState != nil
   288→
   289→	if hasConflict {
   290→		// Try to get the conflicting session's agent type from its state file
   291→		// If it's a different agent type, use that agent's resume command format
   292→		var resumeCmd string
   293→		if existingSessionState != nil && existingSessionState.AgentType != "" {
   294→			if conflictingAgent, agentErr := agent.GetByAgentType(existingSessionState.AgentType); agentErr == nil {
   295→				resumeCmd = conflictingAgent.FormatResumeCommand(existingSessionState.SessionID)
   296→			}
   297→		}
   298→		// Fall back to current agent if we couldn't get the conflicting agent
   299→		if resumeCmd == "" {
   300→			resumeCmd = ag.FormatResumeCommand(existingSessionState.SessionID)
   301→		}
   302→
   303→		// Get CLI command name for fresh start (e.g., "claude" or "gemini")
   304→		cliCmd := "claude"
   305→		if ag.Type() == agent.AgentTypeGemini {
   306→			cliCmd = "gemini"
   307→		}
   308→
   309→		message := fmt.Sprintf(
   310→			"\nYou have an existing session running (%s).\n"+
   311→				"Do you want to continue with this new session (%s)?\n\n"+
   312→				"Yes: Ignore this warning\n"+
   313→				"No: Type /exit, then either:\n"+
   314→				"  • Resume the other session: %s\n"+
   315→				"  • Reset and start fresh: entire reset --force && %s\n\n"+
   316→				"To hide this notice in the future: entire enable --disable-multisession-warning",
   317→			existingSessionState.SessionID,
   318→			sessionID,
   319→			resumeCmd,
   320→			cliCmd,
   321→		)
   322→		// Output blocking JSON response - user must resolve conflict before continuing
   323→		if err := outputHookResponse(message); err != nil {
   324→			return err
   325→		}
   326→	}
   327→
   328→	return nil
   329→}
