    58→// InstallHooks installs Claude Code hooks in .claude/settings.json.
    59→// If force is true, removes existing Entire hooks before installing.
    60→// Returns the number of hooks installed.
    61→func (c *ClaudeCodeAgent) InstallHooks(localDev bool, force bool) (int, error) {
    62→	// Use repo root instead of CWD to find .claude directory
    63→	// This ensures hooks are installed correctly when run from a subdirectory
    64→	repoRoot, err := paths.RepoRoot()
    65→	if err != nil {
    66→		// Fallback to CWD if not in a git repo (e.g., during tests)
    67→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
    68→		if err != nil {
    69→			return 0, fmt.Errorf("failed to get current directory: %w", err)
    70→		}
    71→	}
    72→
    73→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
    74→
    75→	// Read existing settings if they exist
    76→	var settings ClaudeSettings
    77→	var rawSettings map[string]json.RawMessage
    78→
    79→	// rawPermissions preserves unknown permission fields (e.g., "ask")
    80→	var rawPermissions map[string]json.RawMessage
    81→
    82→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
    83→	if readErr == nil {
    84→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
    85→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
    86→		}
    87→		if hooksRaw, ok := rawSettings["hooks"]; ok {
    88→			if err := json.Unmarshal(hooksRaw, &settings.Hooks); err != nil {
    89→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
    90→			}
    91→		}
    92→		if permRaw, ok := rawSettings["permissions"]; ok {
    93→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
    94→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
    95→			}
    96→		}
    97→	} else {
    98→		rawSettings = make(map[string]json.RawMessage)
    99→	}
   100→
   101→	if rawPermissions == nil {
   102→		rawPermissions = make(map[string]json.RawMessage)
   103→	}
   104→
   105→	// If force is true, remove all existing Entire hooks first
   106→	if force {
   107→		settings.Hooks.SessionStart = removeEntireHooks(settings.Hooks.SessionStart)
   108→		settings.Hooks.Stop = removeEntireHooks(settings.Hooks.Stop)
   109→		settings.Hooks.UserPromptSubmit = removeEntireHooks(settings.Hooks.UserPromptSubmit)
   110→		settings.Hooks.PreToolUse = removeEntireHooksFromMatchers(settings.Hooks.PreToolUse)
   111→		settings.Hooks.PostToolUse = removeEntireHooksFromMatchers(settings.Hooks.PostToolUse)
   112→	}
   113→
   114→	// Define hook commands
   115→	var sessionStartCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
   116→	if localDev {
   117→		sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
   118→		stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
   119→		userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
   120→		preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
   121→		postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
   122→		postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
   123→	} else {
   124→		sessionStartCmd = "entire hooks claude-code session-start"
   125→		stopCmd = "entire hooks claude-code stop"
   126→		userPromptSubmitCmd = "entire hooks claude-code user-prompt-submit"
   127→		preTaskCmd = "entire hooks claude-code pre-task"
   128→		postTaskCmd = "entire hooks claude-code post-task"
   129→		postTodoCmd = "entire hooks claude-code post-todo"
   130→	}
   131→
   132→	count := 0
   133→
   134→	// Add hooks if they don't exist
   135→	if !hookCommandExists(settings.Hooks.SessionStart, sessionStartCmd) {
   136→		settings.Hooks.SessionStart = addHookToMatcher(settings.Hooks.SessionStart, "", sessionStartCmd)
   137→		count++
   138→	}
   139→	if !hookCommandExists(settings.Hooks.Stop, stopCmd) {
   140→		settings.Hooks.Stop = addHookToMatcher(settings.Hooks.Stop, "", stopCmd)
   141→		count++
   142→	}
   143→	if !hookCommandExists(settings.Hooks.UserPromptSubmit, userPromptSubmitCmd) {
   144→		settings.Hooks.UserPromptSubmit = addHookToMatcher(settings.Hooks.UserPromptSubmit, "", userPromptSubmitCmd)
   145→		count++
   146→	}
   147→	if !hookCommandExistsWithMatcher(settings.Hooks.PreToolUse, "Task", preTaskCmd) {
   148→		settings.Hooks.PreToolUse = addHookToMatcher(settings.Hooks.PreToolUse, "Task", preTaskCmd)
   149→		count++
   150→	}
   151→	if !hookCommandExistsWithMatcher(settings.Hooks.PostToolUse, "Task", postTaskCmd) {
   152→		settings.Hooks.PostToolUse = addHookToMatcher(settings.Hooks.PostToolUse, "Task", postTaskCmd)
   153→		count++
