   170→		denyJSON, err := json.Marshal(denyRules)
   171→		if err != nil {
   172→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
   173→		}
   174→		rawPermissions["deny"] = denyJSON
   175→		permissionsChanged = true
   176→	}
   177→
   178→	if count == 0 && !permissionsChanged {
   179→		return 0, nil // All hooks and permissions already installed
   180→	}
   181→
   182→	// Marshal hooks and update raw settings
   183→	hooksJSON, err := json.Marshal(settings.Hooks)
   184→	if err != nil {
   185→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
   186→	}
   187→	rawSettings["hooks"] = hooksJSON
   188→
   189→	// Marshal permissions and update raw settings
   190→	permJSON, err := json.Marshal(rawPermissions)
   191→	if err != nil {
   192→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
   193→	}
   194→	rawSettings["permissions"] = permJSON
   195→
   196→	// Write back to file
   197→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
   198→		return 0, fmt.Errorf("failed to create .claude directory: %w", err)
