   415→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
   416→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
   417→	result := make([]ClaudeHookMatcher, 0, len(matchers))
   418→	for _, matcher := range matchers {
   419→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
